css:
.ss-locrail__track{display:flex;gap:20px;overflow-x:auto;scroll-behavior:smooth;scroll-snap-type:x mandatory;padding-bottom:4px}
.ss-locrail__track::-webkit-scrollbar{height:6px}
.ss-locrail__track::-webkit-scrollbar-thumb{background:var(--line)}
.ss-loc{flex:0 0 320px;scroll-snap-align:start;border:1px solid var(--line);background:var(--card);padding:24px;display:flex;flex-direction:column;min-height:310px}
.ss-loc[hidden]{display:none}
.ss-loc__dots{display:flex;gap:6px;min-height:8px;margin-bottom:22px}
.ss-loc__dots span{width:8px;height:8px;border-radius:50%;display:inline-block}
.ss-loc__head{display:flex;align-items:baseline;justify-content:space-between;gap:12px}
.ss-loc__c{display:flex;align-items:baseline;gap:10px;font-family:var(--font-heading);font-weight:800;font-size:19px;margin:0;text-transform:uppercase}
.ss-loc__n{font:700 13px/1 var(--font-body);color:var(--muted)}
.ss-loc__s{font:700 12px/1 var(--font-body);letter-spacing:.08em;color:var(--muted)}
.ss-loc__name{font:700 13px/1.4 var(--font-body);color:var(--ink);margin:14px 0 0}
.ss-loc__phone{font-size:14px;color:#3f3f3f;margin:10px 0 0}
.ss-loc__phone a{color:#3f3f3f;text-decoration:none}
.ss-loc__phone a:hover{color:var(--accent)}
.ss-loc__dir{margin:14px 0 0}
.ss-loc__dir a{font:700 13px/1 var(--font-body);color:var(--accent);text-decoration:none}
.ss-loc__dir a:hover{text-decoration:underline}
.ss-loc__tags{display:flex;flex-wrap:wrap;gap:8px;margin-top:auto;padding-top:24px}
.ss-loc__tags span{border:1px solid var(--line);padding:5px 8px;font:700 10px/1 var(--font-body);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
@media (max-width:640px){.ss-loc{flex-basis:82vw}}
